def harmonic_sum(n):
  # The problem asks to calculate the harmonic sum of (n-1).
  # Let k = n - 1. We need to calculate H_k.
  # The standard definition of harmonic sum H_k is sum_{i=1 to k} (1/i).
  # H_0 is generally defined as 0.
  # H_k = 1/k + H_{k-1} for k > 0.

  # Base case: If k <= 0 (i.e., n - 1 <= 0, which means n <= 1), the sum is 0.
  if n <= 1:
    return 0
  else:
    # Recursive step: H_{n-1} = 1/(n-1) + H_{(n-1)-1}
    # The term is 1/(n-1)
    # The recursive call should compute H_{n-2}, which is harmonic_sum(n-1)
    return 1 / (n - 1) + harmonic_sum(n - 1)

