def count_common(data_dict):
    import collections

    word_counts = collections.Counter()
    for value in data_dict.values():
        if isinstance(value, str):
            # Split the string into words, convert to lowercase, and update counter
            words = value.lower().split()
            word_counts.update(words)
        elif isinstance(value, (list, tuple)):
            # If the value is a list/tuple, iterate through its elements
            for item in value:
                if isinstance(item, str):
                    # Treat each string item in the list/tuple as a potential source of words
                    words = item.lower().split()
                    word_counts.update(words)

def count_common(word_counts_dict):
    if not word_counts_dict:
        return []

    max_count = max(word_counts_dict.values())

    most_common_words = [word for word, count in word_counts_dict.items() if count == max_count]

    return most_common_words

