def index_on_inner_list(list_of_lists, index):
    n = len(list_of_lists)
    for i in range(n):
        for j in range(0, n - i - 1):
            if list_of_lists[j][index] > list_of_lists[j + 1][index]:
                list_of_lists[j], list_of_lists[j + 1] = list_of_lists[j + 1], list_of_lists[j]
    return list_of_lists

